function personSpacing(){if(getSubjectKind()!=='human')return getSubjectKind()==='largeDog'?1.2:.7;return $('#pose').value==='recline'?1.5:.60;}

const promptCommonText='添付画像を構図の下絵として、下記の【設定】に従って実写風の画像を生成してください。\n\n被写体の数・配置・ポーズ、画面内での大きさ、重なり方、カメラの位置・高さ・向き、魚眼レンズの遠近感と歪みを保ってください。\n手前の手足が大きく見える誇張を、通常の広角写真へ補正しないでください。\n\n被写体を自然な骨格・関節を持つ実写風の人物または動物に置き換えてください。背景にも被写体と一致するカメラ位置、魚眼の投影、光の方向、影を適用し、一枚の写真として自然になじませてください。\n\nマネキン、関節の継ぎ目、グリッド、操作画面、文字、ロゴは残さないでください。';
const promptLabels=['背景','時間帯','天候・季節','人物の設定','服装','表情','雰囲気・感情','光','仕上がり'];
const promptExamples={rooftop:['街並みが見える屋上。床に小さな水たまり。','夕焼け','夏の終わり、雨上がり','仲のよい成人の友達。人数・配置は下絵に従う。','夏のカジュアルな私服','友達同士の自然な笑顔','夏の終わりの高揚感、自由、懐かしさ','暖かい夕日、柔らかい逆光、濡れた床の反射','自然な肌と布の質感、控えめなフィルム粒子'],city:['濡れた舗道と店の明かりがある都会の路地','夜','秋、小雨が上がった直後','成人の人物。人数・配置は下絵に従う。','落ち着いた色のストリートファッション','ふと振り返った自然な表情','映画のワンシーンのような静かな高揚感','青い街灯と暖かい店内灯、路面の反射','実写写真。自然な肌、柔らかな光のにじみ'],forest:['木漏れ日が差す緑の森。遠くに小さな小川','朝','初夏、晴れ','成人の人物。人数・配置は下絵に従う。','軽いリネンの服や動きやすい私服','自然で穏やかな笑顔','冒険の始まり、開放感、みずみずしさ','葉を透ける朝日、柔らかな木漏れ日','自然光の実写写真。葉と服の繊細な質感']};
$('#commonPrompt').value=promptCommonText;$('#promptFields').innerHTML=promptLabels.map((label,i)=>'<label for="promptVar'+i+'">'+label+'<textarea id="promptVar'+i+'" data-prompt-var rows="2"></textarea></label>').join('');
function buildPromptParts(){const settings='【設定】\n'+promptLabels.map((label,i)=>{const value=$('#promptVar'+i).value.trim();return value?label+'：'+value:'';}).filter(Boolean).join('\n');const background=$('#promptBackgroundPhoto').checked?'\n\n【参照画像の役割】\n画像1は構図の参照、画像2は背景の参照です。画像2の被写体や素材感を活用し、画像1のカメラ位置と魚眼の遠近感に合わせて構成してください。':'';return{common:promptCommonText,settings:settings+background,all:promptCommonText+'\n\n'+settings+background};}
function updatePromptPreview(){$('#completePrompt').value=buildPromptParts().all;$('#promptCopyStatus').textContent='共通部分＋現在の設定をコピーできます。';}
function setPromptExample(name){promptExamples[name].forEach((v,i)=>$('#promptVar'+i).value=v);document.querySelectorAll('[data-prompt-preset]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.promptPreset===name)));updatePromptPreview();}
document.querySelectorAll('[data-prompt-preset]').forEach(b=>b.onclick=()=>setPromptExample(b.dataset.promptPreset));document.querySelectorAll('[data-prompt-var],#promptBackgroundPhoto').forEach(e=>e.addEventListener('input',()=>{document.querySelectorAll('[data-prompt-preset]').forEach(b=>b.setAttribute('aria-pressed','false'));updatePromptPreview();}));
document.querySelectorAll('[data-copy-prompt]').forEach(b=>b.onclick=async()=>{const kind=b.dataset.copyPrompt,text=buildPromptParts()[kind];try{await navigator.clipboard.writeText(text);$('#promptCopyStatus').textContent=(kind==='all'?'全文':kind==='common'?'共通部分':'設定部分')+'をコピーしました。下絵PNGと一緒に生成AIへ貼り付けてください。';}catch{$('.prompt-final').open=true;$('#completePrompt').value=text;$('#completePrompt').focus();$('#completePrompt').select();$('#promptCopyStatus').textContent='自動コピーを利用できませんでした。選択された文章を手動でコピーしてください。';}});
document.querySelectorAll('.openPromptGuide').forEach(b=>b.onclick=()=>{if($('#exportDialog').open)$('#exportDialog').close();$('#promptGuideDetails').open=true;$('#promptGuide').scrollIntoView({behavior:'smooth',block:'start'});});setPromptExample('rooftop');

function getSubjectKind(){return $('#subject').value||'human';}
function entityPlacement(j,n=+$('#people').value){const d=+$('#distance').value,gap=personSpacing();if(n<=3)return{x:(j-(n-1)/2)*gap,z:d+(j%2)*.10};const columns=Math.ceil(Math.sqrt(n)),rows=Math.ceil(n/columns),row=Math.floor(j/columns),col=j%columns;return{x:(col-(Math.min(columns,n-row*columns)-1)/2)*gap,z:d+row*Math.max(getSubjectKind()==='human'?.68:.85,gap*.9)};}
function crowdCenterZ(){const n=+$('#people').value;return n<=3?+$('#distance').value:(entityPlacement(0,n).z+entityPlacement(n-1,n).z)/2;}
function animalTargetY(){const kind=getSubjectKind(),scale=kind==='largeDog'?1:kind==='smallDog'?.55:.5;return -1.635+scale*(['down','sleep','play'].includes($('#pose').value)?.24:.6);}
function buildPeople(){buildGeometry();entities=[];for(let i=0;i<shapes.length;i++){const s=shapes[i],id=s.entity;let g=entities[entities.length-1];if(!g||g.id!==id){const p=entityPlacement(id);g={id,start:i,end:i,min:[Infinity,Infinity,Infinity],max:[-Infinity,-Infinity,-Infinity],worldX:p.x,worldZ:p.z};entities.push(g);}g.end=i+1;for(let axis=0;axis<3;axis++){const radius=s.e?s.e[axis]:s.r;g.min[axis]=Math.min(g.min[axis],s.a[axis]-radius,s.b[axis]-radius);g.max[axis]=Math.max(g.max[axis],s.a[axis]+radius,s.b[axis]+radius);}}for(const g of entities){g.center=g.min.map((v,i)=>(v+g.max[i])/2);g.radius=Math.hypot(...g.max.map((v,i)=>(v-g.min[i])/2));g.distance2=g.center.reduce((v,n)=>v+n*n,0);}}
function buildAnimal(j,base,pose){const kind=getSubjectKind(),cat=kind==='cat',scale=kind==='largeDog'?1:kind==='smallDog'?.55:.5,c=cat?[179,187,197]:[[201,190,172],[163,176,184],[193,178,165]][j%3],dark=c.map(v=>v*.55),point=(x,h,z)=>[base.x+x*scale-cameraX,-1.635+h*scale-cameraY,base.z+z*scale-cameraZ];const ell=(x,h,z,r,col=c)=>{const a=point(x,h,z);shapes.push({a,b:a,r:1,e:r.map(v=>v*scale),c:col,entity:j});},bone=(a,b,r,col=c)=>shapes.push({a:point(...a),b:point(...b),r:r*scale,c:col,entity:j});let headH=.76,headZ=-.36,headX=0;
if(pose==='sit'){ell(0,.34,.12,[.18,.26,.24]);for(const side of[-1,1]){ell(side*.14,.15,.24,[.10,.14,.17]);bone([side*.12,.40,-.08],[side*.12,.07,-.14],.055);ell(side*.12,.05,-.20,[.07,.045,.10]);}headZ=-.22;}
else if(pose==='sleep'){ell(0,.16,.03,[.25,.15,.28]);headH=.18;headZ=-.22;headX=.13;for(const side of[-1,1])ell(side*.13,.07,-.06,[.09,.05,.14]);}
else if(pose==='down'){ell(0,.19,0,[.18,.16,.38]);headH=.34;headZ=-.41;for(const side of[-1,1]){bone([side*.12,.16,-.23],[side*.13,.07,-.53],.055);ell(side*.13,.045,-.59,[.07,.04,.10]);ell(side*.15,.10,.29,[.10,.085,.16]);}}
else if(pose==='play'){ell(0,.39,.10,[.18,.18,.35]);headH=.25;headZ=-.43;for(const side of[-1,1]){bone([side*.12,.23,-.2],[side*.13,.06,-.58],.055);ell(side*.13,.045,-.64,[.07,.04,.1]);bone([side*.12,.57,.30],[side*.13,.06,.35],.055);ell(side*.13,.045,.30,[.07,.04,.10]);}}
else{ell(0,.46,0,[cat?.15:.18,.19,cat?.34:.38]);for(const side of[-1,1])for(const z of[-.25,.25]){bone([side*.12,.43,z],[side*.13,.07,z],.055);ell(side*.13,.045,z-.055,[.065,.04,.10]);}}
if(pose!=='sleep')bone([0,pose==='down'?.22:pose==='play'?.32:.49,headZ+.15],[headX,headH-.07,headZ],.10);ell(headX,headH,headZ,[cat?.105:.12,cat?.105:.115,.115]);ell(headX,headH-.035,headZ-(cat?.095:.13),[cat?.065:.08,.058,cat?.055:.11]);ell(headX,headH-.02,headZ-(cat?.146:.23),[.025,.02,.02],dark);
for(const side of[-1,1]){ell(headX+side*.10,headH+(cat?.105:.01),headZ+.015,cat?[.038,.085,.032]:[.045,.10,.036]);ell(headX+side*.05,headH+.028,headZ-.105,pose==='sleep'?[.021,.006,.008]:[.018,.018,.012],dark);}
if(cat){bone([0,.51,.29],[.025,.72,.49],.035);bone([.025,.72,.49],[.03,.96,.48],.028);}else{bone([0,pose==='sleep'?.18:.50,.30],[.03,pose==='sleep'?.12:.65,.55],.045);bone([.03,pose==='sleep'?.12:.65,.55],[.08,pose==='sleep'?.09:.76,.63],.028);}}
function applyViewPreset(view){if(scene!=='portrait')showPortrait();const d=+$('#distance').value,animal=getSubjectKind()!=='human';cameraX=cameraY=cameraZ=yaw=pitch=0;if(animal){if(view==='lying')setPoseValue('sleep');cameraY=animalTargetY();cameraZ=d-(view==='close'?.55:1.1);if(view==='top'||view==='lying'){cameraY=animalTargetY()+1.0;cameraZ=d;pitch=-Math.PI/2;}else if(view==='low'){cameraY=-1.59;cameraZ=d-.6;aimAtSubject();}else if(view==='close'){buildPeople();let lo=d-1.5,hi=d;for(let i=0;i<32;i++){cameraZ=(lo+hi)/2;buildPeople();if(nearestSurface()<focusMinimum())hi=cameraZ;else lo=cameraZ;}cameraZ=lo;}}
else if(view==='feet'){if(!['seated','supine'].includes($('#pose').value))setPoseValue('seated');cameraY=$('#pose').value==='seated'?-1.08:-1.43;cameraZ=d-1.35;pitch=.12;}
else if(view==='lying'){if(!['recline','supine'].includes($('#pose').value))setPoseValue('supine');cameraY=.4;cameraZ=d;pitch=-Math.PI/2;}
else if(view==='top'){cameraY=+$('#people').value>3?2.3:.8;cameraZ=crowdCenterZ();pitch=-Math.PI/2;}
else if(view==='low'){cameraY=-1.59;cameraZ=d-.02;pitch=Math.PI/2;}
else if(view==='close'){cameraY=.015;let lo=d-1.5,hi=d;for(let i=0;i<35;i++){cameraZ=(lo+hi)/2;buildPeople();if(nearestSurface()<focusMinimum())hi=cameraZ;else lo=cameraZ;}cameraZ=lo;}
else if(+$('#people').value>3){cameraY=2.2;cameraZ=-1.2;aimAtSubject();}escapeCollision();syncSimple();}
const humanPoses=Array.from($('#pose').options,o=>[o.value,o.textContent]);const animalPoses=[['stand','立つ'],['sit','おすわり'],['down','伏せ'],['sleep','丸く寝る'],['play','前脚を伸ばす']];let optionsUnlocked=false;try{optionsUnlocked=localStorage.getItem('gyogyotaro-extra-options-v1')==='unlocked';}catch{}
function setPoseValue(value){const valid=(getSubjectKind()==='human'?humanPoses:animalPoses).map(p=>p[0]);$('#pose').value=valid.includes(value)?value:'stand';$('#simplePose').value=$('#pose').value;}
function refreshPoseMenus(){const old=$('#pose').value,items=getSubjectKind()==='human'?humanPoses:animalPoses;for(const id of['pose','simplePose'])$('#'+id).replaceChildren(...items.map(([v,label])=>{const o=document.createElement('option');o.value=v;o.textContent=label;return o;}));setPoseValue(old);}
function syncUnlockUI(){for(const id of['subject','simpleSubject'])for(const o of $('#'+id).options)if(o.value!=='human'){o.disabled=!optionsUnlocked;o.textContent=({smallDog:'小型犬',largeDog:'大型犬',cat:'猫'})[o.value]+(optionsUnlocked?'':' 🔒');}for(const id of['people','simplePeople'])for(const o of $('#'+id).options){const n=+o.value;if(n>3)o.disabled=!optionsUnlocked;o.textContent=n+(getSubjectKind()==='human'?'人':'匹')+(n>3&&!optionsUnlocked?' 🔒':'');}$('#unlockOptions').textContent=optionsUnlocked?'追加オプション 開放済み ✓':'課金してオプションを追加する';$('#unlockHint').textContent=optionsUnlocked?'100体表示・小型犬・大型犬・猫が使えます。':'擬似課金です。実際の支払いはありません。';}
function changeSubject(value){if(value!=='human'&&!optionsUnlocked)return;$('#subject').value=value;$('#simpleSubject').value=value;refreshPoseMenus();syncUnlockUI();showPortrait();applyViewPreset('eye');}
$('#subject').onchange=()=>changeSubject($('#subject').value);$('#simpleSubject').onchange=()=>changeSubject($('#simpleSubject').value);
for(const id of['people','simplePeople'])$('#'+id).addEventListener('change',()=>{if(+$('#people').value>3&&!optionsUnlocked){$('#people').value='3';$('#simplePeople').value='3';}if(+$('#people').value>3)applyViewPreset('eye');});
const syncBeforeSubject=syncSimple;syncSimple=function(){syncBeforeSubject();$('#simpleSubject').value=$('#subject').value;};
let unlockStep=0;const unlockMessages=['ほんとに課金するの？','ほんとに？','そんなに気に入ってくれたの？','ありがとう。','感謝の気持ちとしてオプションが開放されました'];const unlockLabels=['うん、進む','ほんとに！','気に入った！','こちらこそ','オプションを使う'];function showUnlockStep(){$('#unlockTitle').textContent=unlockMessages[unlockStep];$('#unlockMessage').textContent=unlockStep===4?'100体表示・小型犬・大型犬・猫と、それぞれの専用ポーズが使えます。':'';$('#unlockNext').textContent=unlockLabels[unlockStep];$('#unlockCancel').hidden=unlockStep===4;}
$('#unlockOptions').onclick=()=>{unlockStep=optionsUnlocked?4:0;showUnlockStep();$('#unlockDialog').showModal();};$('#unlockCancel').onclick=()=>$('#unlockDialog').close();$('#unlockNext').onclick=()=>{if(unlockStep===4){$('#unlockDialog').close();return;}unlockStep++;if(unlockStep===4){optionsUnlocked=true;try{localStorage.setItem('gyogyotaro-extra-options-v1','unlocked');}catch{}syncUnlockUI();}showUnlockStep();};syncUnlockUI();syncSimple();schedule();
